\set ON_ERROR_STOP on
begin;
\ir group_scope_fixture.sql
create function pg_temp.expect_event_error(query text,expected text)returns void language plpgsql as $$begin execute query;raise exception 'Expected error %',expected;exception when others then if sqlerrm<>expected then raise;end if;end $$;
do $$declare owner uuid:=extensions.gen_random_uuid();a uuid:=extensions.gen_random_uuid();b uuid:=extensions.gen_random_uuid();pending uuid:=extensions.gen_random_uuid();admin uuid:=extensions.gen_random_uuid();allowlist uuid:=extensions.gen_random_uuid();page uuid:=extensions.gen_random_uuid();event uuid;ra uuid;rb uuid;rp uuid;request uuid;official uuid;support uuid;followup uuid;wave uuid;qr text;r jsonb;again jsonb;first_time text;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:event-op-'||owner,owner||'@example.test'),(a,'did:privy:event-op-'||a,a||'@example.test'),(b,'did:privy:event-op-'||b,b||'@example.test'),(pending,'did:privy:event-op-'||pending,pending||'@example.test'),(admin,'did:privy:event-op-'||admin,admin||'@example.test');
 insert into public.admin_allowlist(id,email,role,active)values(allowlist,admin||'@example.test','admin',true);
 insert into public.user_profiles(app_user_id,nickname,nickname_normalized)values(a,'QR member','qr member'),(b,'Manual member','manual member'),(pending,'Pending member','pending member');
 insert into public.group_pages(id,kind,name)values(page,'hobby','Event operations fixture');
 insert into public.group_memberships(page_id,app_user_id,role)values(page,owner,'owner'),(page,a,'member'),(page,b,'member'),(page,pending,'member');
 r:=public.group_activities_dispatch('event-save',owner,page,null,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'title','Operations fixture','description','Real attendance','startsAt',clock_timestamp()-interval'1 hour','endsAt',clock_timestamp()+interval'1 hour','opensAt',clock_timestamp()-interval'1 day','closesAt',clock_timestamp()+interval'30 minutes','location','Fixture location','capacity',3,'requiresApproval',true,'state','published'));event:=(r#>>'{event,id}')::uuid;
 perform public.group_activities_dispatch('event-apply',a,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid()));
 perform public.group_activities_dispatch('event-apply',b,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid()));
 perform public.group_activities_dispatch('event-apply',pending,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid()));
 select id into ra from public.group_event_registrations where event_id=event and app_user_id=a;select id into rb from public.group_event_registrations where event_id=event and app_user_id=b;select id into rp from public.group_event_registrations where event_id=event and app_user_id=pending;
 perform public.group_activities_dispatch('event-review-participant',owner,page,event,ra,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','confirm'));
 perform public.group_activities_dispatch('event-review-participant',owner,page,event,rb,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','confirm'));
 r:=public.group_activities_dispatch('event-participants',owner,page,event,null,'{"search":"Manual","limit":1}');
 if jsonb_array_length(r->'items')<>1 or r#>>'{items,0,id}'<>rb::text or r->>'nextCursor'is not null then raise exception 'Participant search before cursor failed';end if;
 qr:=public.group_activities_dispatch('event-ticket',a,page,event)->>'qrPayload';request:=extensions.gen_random_uuid();
 r:=public.group_activities_dispatch('event-check-in',owner,page,event,null,jsonb_build_object('requestId',request,'qrPayload',qr));first_time:=r->>'checkedInAt';
 if r->>'alreadyCheckedIn'is distinct from'false'or r->>'replayed'is distinct from'false'then raise exception 'First scan misclassified';end if;
 again:=public.group_activities_dispatch('event-check-in',owner,page,event,null,jsonb_build_object('requestId',request,'qrPayload',qr));
 if again is distinct from r||'{"replayed":true}'::jsonb then raise exception 'Lost-response scan replay changed original result';end if;
 again:=public.group_activities_dispatch('event-check-in',owner,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'qrPayload',qr));
 if again->>'alreadyCheckedIn'is distinct from'true'or again->>'replayed'is distinct from'false'or again->>'checkedInAt'<>first_time then raise exception 'New scan did not identify already checked in';end if;
 if(select count(*)from public.group_event_checkin_audit where registration_id=ra)<>2 then raise exception 'QR retry duplicated audit';end if;
 perform pg_temp.expect_event_error(format('select public.group_activities_dispatch(%L,%L,%L,%L,%L,%L::jsonb)','event-manual-check-in',owner,page,event,rp,jsonb_build_object('requestId',extensions.gen_random_uuid(),'confirmedName','Pending member','reason','QR failed')),'GROUP_ACTIVITY_FORBIDDEN');
 perform pg_temp.expect_event_error(format('select public.group_activities_dispatch(%L,%L,%L,%L,%L,%L::jsonb)','event-manual-check-in',owner,page,event,rb,jsonb_build_object('requestId',extensions.gen_random_uuid(),'confirmedName','Wrong member','reason','QR failed')),'GROUP_ACTIVITY_INVALID');
 update public.app_users set status='disabled'where id=b;
 qr:=public.group_activities_dispatch('event-ticket',a,page,event)->>'qrPayload';
 select 'kyaa-event:'||id||':'||encode(ticket_token,'hex')into qr from public.group_event_registrations where id=rb;
 perform pg_temp.expect_event_error(format('select public.group_activities_dispatch(%L,%L,%L,%L,null,%L::jsonb)','event-check-in',owner,page,event,jsonb_build_object('requestId',extensions.gen_random_uuid(),'qrPayload',qr)),'GROUP_ACTIVITY_FORBIDDEN');
 perform pg_temp.expect_event_error(format('select public.group_activities_dispatch(%L,%L,%L,%L,%L,%L::jsonb)','event-manual-check-in',owner,page,event,rb,jsonb_build_object('requestId',extensions.gen_random_uuid(),'confirmedName','Manual member','reason','QR failed')),'GROUP_ACTIVITY_FORBIDDEN');
 update public.app_users set status='active'where id=b;
 request:=extensions.gen_random_uuid();r:=public.group_activities_dispatch('event-manual-check-in',owner,page,event,rb,jsonb_build_object('requestId',request,'confirmedName','Manual member','reason','Device cannot display QR'));
 again:=public.group_activities_dispatch('event-manual-check-in',owner,page,event,rb,jsonb_build_object('requestId',request,'confirmedName','Manual member','reason','Device cannot display QR'));
 if again is distinct from r||'{"replayed":true}'::jsonb or(select count(*)from public.group_event_checkin_audit where registration_id=rb and method='manual')<>1 or(select status from public.group_event_registrations where id=rp)<>'pending'then raise exception 'Manual check-in altered approval or duplicated audit';end if;
 update public.group_events set starts_at=clock_timestamp()-interval'2 hours',ends_at=clock_timestamp()-interval'1 hour',closes_at=clock_timestamp()-interval'90 minutes'where id=event;
 perform public.group_activities_dispatch('event-review-write',a,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'body','Actual linked review'));
 r:=public.group_activities_dispatch('event-support',owner,page,event);if r->>'attendanceCount'<>'2'or r->>'reviewCount'<>'1'then raise exception 'Support summary invented attendance/reviews';end if;
 r:=public.group_activities_dispatch('event-support-submit',owner,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'description','Original supporting evidence','sourceUrl','https://example.test/source?query=kept#evidence'));support:=(r->>'id')::uuid;
 perform public.group_activities_dispatch('event-support-review',admin,page,event,support,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','request_changes','reason','Please link remaining evidence'),allowlist);
 r:=public.group_activities_dispatch('event-support-submit',owner,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'description','Supplemented supporting evidence','sourceUrl','https://example.test/new','previousSubmissionId',support));followup:=(r->>'id')::uuid;
 if r->>'revision'<>'2'or r->>'previousSubmissionId'<>support::text or(select description from public.group_event_support_submissions where id=support)<>'Original supporting evidence'or(select source_url from public.group_event_support_submissions where id=support)<>'https://example.test/source?query=kept#evidence'then raise exception 'Support revision overwrote source';end if;
 perform public.group_activities_dispatch('event-support-review',admin,page,event,followup,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','approve'),allowlist);
 if(select official_revision from public.group_events where id=event)is not null then raise exception 'Support approval changed official event status';end if;
 perform pg_temp.expect_event_error(format('update public.group_event_support_submissions set description=%L where id=%L','Changed',support),'GROUP_ACTIVITY_CONFLICT');
 r:=public.group_activities_dispatch('admin-event-support',admin,null,null,null,'{"limit":1}',allowlist);if jsonb_array_length(r->'items')<>1 or r->>'nextCursor'is null then raise exception 'Admin support cursor missing';end if;
 r:=public.group_activities_dispatch('official-submit',owner,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'description','Original official application','sourceUrl','https://example.test/official'));official:=(r->>'id')::uuid;
 r:=public.group_activities_dispatch('official-review',admin,page,event,official,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','start_review'),allowlist);if r->>'status'is distinct from'reviewing'then raise exception 'Official review start not persisted';end if;
 perform public.group_activities_dispatch('official-review',admin,page,event,official,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','request_changes','reason','Please supplement'),allowlist);
 r:=public.group_activities_dispatch('official-submit',owner,page,event,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'description','Supplemented official application','previousApplicationId',official));
 r:=public.group_activities_dispatch('official-applications',owner,page,event);if jsonb_array_length(r->'items')<>2 or(select description from public.group_official_event_applications where id=official)<>'Original official application'then raise exception 'Official application history overwritten';end if;
 perform pg_temp.expect_event_error(format('select public.group_activities_dispatch(%L,%L,%L,%L)','event-support',a,page,event),'GROUP_ACTIVITY_FORBIDDEN');
 wave:=pg_temp.group_scope_fixture(a,false);
 perform pg_temp.expect_event_error(format('select public.group_activities_dispatch(%L,%L,%L)','activities',a,wave),'GROUP_ACTIVITY_NOT_FOUND');
 perform pg_temp.expect_event_error(format('select public.group_activities_dispatch(%L,null,%L)','activities',wave),'GROUP_ACTIVITY_NOT_FOUND');
 perform pg_temp.group_scope_fixture(a,true);
 r:=public.group_activities_dispatch('activities',a,wave);if not(r?'events')then raise exception 'Checked-in WAVE member denied activities';end if;
 if has_function_privilege('service_role','public.group_activities_dispatch_before_operations(text,uuid,uuid,uuid,uuid,jsonb,uuid)','EXECUTE')then raise exception 'Private operations bypass exposed';end if;
 raise notice 'PASS scan/replay/rescan distinctions, audited confirmed-only manual check-in, participant search, official/support immutable revision history and scope gates';
end $$;
rollback;
